            if len(y)>1 and owner_ok(y[1]):
                tags.add(n)
            continue
        if n=='third_parties':
            tags.add(n)
            continue
        i=1
        while i<len(y):
            if isinstance(y[i],list):
                todo.append(y[i])
            i+=1
    return tags

def unique(xs):
