def has_word(t,p):
    return re.search(p,t,re.I) is not None

def add_statement(out,term,ids):
    for s in out:
        if s.get('term')==term:
            return
    out.append({'term':term,'support_ids':ids})

def add_once(xs,x):
    if x not in xs:
        xs.append(x)

def make_union(xs):
    if len(xs)==1:
        return xs[0]
    v=xs[len(xs)-1]
    i=len(xs)-2
    while i>=0:
        v=['participant_union',xs[i],v]
        i-=1
    return v

def make_condition(t):
    cs=[]
    if 'need to know' in t or 'need-to-know' in t or 'need-to know' in t:
        cs.append(['need_to_know','stated purpose'])
    if any_phrase(t,['bound by obligations of confidentiality','treat the confidential information as confidential','obliged by their contracts','obligated to protect','terms and conditions no less protective']):
        cs.append(['confidentiality_bound','source-stated confidentiality obligation'])
    if any_phrase(t,['only to the extent necessary','disclosure is necessary','as deemed necessary','reasonably necessary']):
        cs.append(['extent_necessary','source-stated purpose'])
    if not cs:
        return ['no_condition']
    v=cs[0]
    i=1
    while i<len(cs):
        v=['and_condition',v,cs[i]]
        i+=1
    return v

def permission_segment(t):
    marks=['may disclose','may share','internally share','restrict access','except in confidence','except to such']
    best=-1
    for m in marks:
        p=t.rfind(m)
        if p>best:
            best=p
    if best<0 and 'not to disclose' in t and ' except ' in t:
        best=t.rfind(' except ')
    return t[best:] if best>=0 else t

def recipient_terms(t):
    owner=['receiving_party']
    if any_phrase(t,["affiliates' officers","affiliates’ officers","affiliate's officers","affiliate’s officers"]):
        owner=['affiliates_of',['receiving_party']]
    xs=[]
    if has_word(t,r'\bemployees?\b'):
        xs.append(['employees_of',owner])
    if has_word(t,r'\bdirectors?\b'):
        xs.append(['directors_of',owner])
    if has_word(t,r'\bofficers?\b'):
        xs.append(['officers_of',owner])
    if any_phrase(t,['legal advisors','legal advisers','attorneys','legal counsel']):
        xs.append(['legal_advisors_of',owner])
    if any_phrase(t,['financial advisors','financial advisers']):
        xs.append(['financial_advisors_of',owner])
    if any_phrase(t,['professional advisors','professional advisers']):
        xs.append(['professional_advisors_of',owner])
    if has_word(t,r'\baccountants?\b'):
        xs.append(['accountants_of',owner])
    if has_word(t,r'\bconsultants?\b'):
        xs.append(['consultants_of',owner])
    if has_word(t,r'\bagents?\b'):
        xs.append(['agents_of',owner])
    if has_word(t,r'\bcontractors?\b'):
        xs.append(['independent_contractors_of',owner])
    if has_word(t,r'\blenders?\b'):
        xs.append(['lenders_of',owner])
    if 'internally share' in t and not xs:
        xs.append(['internal_personnel_of',['receiving_party']])
    if not xs and 'representatives' in t:
        xs.append(['representatives_of',['receiving_party']])
    if not xs and any_phrase(t,['third parties','third party']):
        xs.append(['third_parties'])
    return xs

def make_exceptions(t,perm):
    es=[]
    if any_phrase(t,['prior written consent','prior, written consent','prior written approval','prior written permission','expressly authorized in writing','express permission']):
        es.append(['authorization_exception','source-stated written authorization'])
    if any_phrase(t,['required to analyze','required to fulfil','required to fulfill']):
        es.append(['purpose_exception','source-stated required activity'])
    if any_phrase(t,['except as expressly permitted under','except as permitted under','except as provided in','except as provided under']):
        es.append(['cross_reference_exception','source-stated disclosure cross-reference'])
    if perm is not None:
        es.append(['permission_exception',perm])
    if not es:
        return ['no_exceptions']
    v=['exception_set',es[0]]
    i=1
    while i<len(es):
        v=['add_exception',v,es[i]]
        i+=1
    return v

def parse_context(raw,ids,out,refs):
    t=raw.casefold()
    if not t:
        return
    if ('“representative” means' in t or '"representative" means' in t or 'representative means' in t) and any_phrase(t,['employee','director','officer','agent','accountant','attorney','contractor']):
        cats=recipient_terms(t)
        fixed=[]
        for c in cats:
            if len(c)>1:
                c[1]=['party']
            fixed.append(c)
        if fixed:
            add_statement(out,['define_representative',['party'],make_union(fixed)],ids)
    if any_phrase(t,['information about employees','employee lists and records','human resources data']) and 'confidential' in t:
        add_statement(out,['confidential_information_includes',['employee_information',['disclosing_party']]],ids)
    if 'whereas' in t and 'may' in t and 'disclos' in t and 'confidential information' in t:
        add_statement(out,['possible_disclosure_description',['disclosing_party'],['confidential_information'],['receiving_party']],ids)
    if 'confidential information' not in t and 'such information' not in t and 'the same' not in t:
        return
    actor=['named_recipient','Volunteer'] if 'volunteer agrees' in t else ['receiving_party']
    if 'neither it nor its representatives' in t and any_phrase(t,['any other person','any other organization','other person or organization']):
        group=['participant_union',['receiving_party'],['representatives_of',['receiving_party']]]
        ex=make_exceptions(t,None)
        add_statement(out,['prohibition',group,['disclose',['confidential_information'],['outsiders_to',group]],['no_condition'],ex],ids)
        return
    pmark=any_phrase(t,['may disclose','may share','internally share','restrict access']) or ('not to disclose' in t and ' except ' in t)
    perm=None
    if pmark:
        seg=permission_segment(t)
        cats=recipient_terms(seg)
        if cats:
            perm=['permission',actor,['disclose',['confidential_information'],make_union(cats)],make_condition(t)]
            add_statement(out,perm,ids)
    third=any_phrase(t,['third parties','third party'])
    neg=any_phrase(t,['shall not disclose','not to disclose','not to, without','not to, directly','not disclose, allow access','not to divulge'])
    if third and neg:
        ex=make_exceptions(t,perm)
        add_statement(out,['prohibition',actor,['disclose',['confidential_information'],['third_parties']],['no_condition'],ex],ids)
        if any_phrase(t,['except as expressly permitted under','except as permitted under','except as provided in','except as provided under']):
            add_once(refs,'unresolved disclosure cross-reference')

def has_tag(term,name):
    todo=[term]
    while todo:
        x=todo.pop()
        if isinstance(x,list) and x:
            if x[0]==name:
                return True
            i=1
            while i<len(x):
                if isinstance(x[i],list):
                    todo.append(x[i])
                i+=1
    return False

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    queries=_dr_queries(spans)
    if inputs.get('phase')=='plan':
        return {'queries':queries}
    statements=[]
    refs=[]
    texts=[]
    ids=[]
    for s in spans:
        raw=s.get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        texts.append(raw)
        ids.append(s.get('id'))
        parse_context(raw,[s.get('id')],statements,refs)
    i=0
    while i+1<len(texts):
        w=texts[i]+' '+texts[i+1]
        lw=w.casefold()
        if ('restrict access' in lw and 'such employees' in lw) or ('neither it nor its representatives' in lw and any_phrase(lw,['any other person','other person or organization'])):
            parse_context(w,[ids[i],ids[i+1]],statements,refs)
        i+=1
    unresolved=[]
    answers={}
    for a in inputs.get('semantic_answers',[]):
        aid=a.get('id')
        if aid not in answers:
            answers[aid]=a
        else:
            unresolved.append('Duplicate semantic answer for '+str(aid)+'.')
    for q in queries:
        qid=q.get('id')
        a=answers.get(qid)
        if a is None:
            unresolved.append('Missing disposal/retention source-role judgment for '+qid+'.')
            continue
        if a.get('operation')!='disposal_retention_clause_role':
            unresolved.append('Mismatched semantic operation for '+qid+'.')
            continue
        choice=a.get('choice','unknown')
        if choice=='unknown':
            unresolved.append('The disposal/retention role remains unknown for '+qid+'.')
            continue
        if choice=='supplemental_linked_effect':
            unresolved.append('A linked disposal or retention effect could not be represented safely from the queried units for '+qid+'.')
            continue
        if choice=='no_relevant_operative_effect':
            continue
        raw,window_ids=_dr_window(spans,q.get('unit_ids',[]))
        temp=[]
        parse_disposal(raw,window_ids,temp)
        if choice=='operative_disposal':
            found=_dr_add_filtered(statements,temp,['disposal_obligation'])
            if 'disposal_obligation' not in found:
                unresolved.append('An operative disposal judgment could not be mapped without inventing scope for '+qid+'.')
        elif choice=='operative_retention_permission':
            found=_dr_add_filtered(statements,temp,['retention_permission'])
            if 'retention_permission' not in found:
                unresolved.append('An operative retention permission could not be mapped without inventing scope for '+qid+'.')
        elif choice=='operative_retention_prohibition':
            found=_dr_add_filtered(statements,temp,['retention_prohibition'])
            if 'retention_prohibition' not in found:
                unresolved.append('An operative retention prohibition could not be mapped without inventing scope for '+qid+'.')
        elif choice=='operative_disposal_and_retention_permission':
            found=_dr_add_filtered(statements,temp,['disposal_obligation','retention_permission'])
            if 'disposal_obligation' not in found or 'retention_permission' not in found:
                unresolved.append('The combined disposal and retention judgment could not be mapped completely for '+qid+'.')
        else:
            unresolved.append('Unsupported disposal/retention source-role choice for '+qid+'.')
    has_permission=False
    has_definition=False
    needs_definition=False
    for s in statements:
        term=s.get('term')
        if isinstance(term,list) and term:
            if term[0]=='permission' or has_tag(term,'permission_exception'):
                has_permission=True
            if term[0]=='define_representative':
                has_definition=True
            if term[0] in ('permission','prohibition') and has_tag(term,'representatives_of'):
                needs_definition=True
    if refs and not has_permission:
        unresolved.append('A disclosure exception refers to another provision, but no operative recipient permission was resolved from the current source.')
    if needs_definition and not has_definition:
        unresolved.append('An operative norm uses Representatives, but their current-source membership or owner binding was not resolved.')
    return {'statements':statements,'complete':not unresolved,'unresolved':unresolved}

def make_information_bundle(xs):
    if len(xs)==1:
        return xs[0]
    v=xs[len(xs)-1]
    i=len(xs)-2
    while i>=0:
        v=['information_bundle',xs[i],v]
        i-=1
    return v

def disposal_information(t):
    xs=[['confidential_information']]
    if 'copy' in t or 'copies' in t:
        xs.append(['copies_of',['confidential_information']])
    if any_phrase(t,['compilation','analysis','derivative work','notes or abstracts','notes and abstracts']):
        xs.append(['derivative_materials_of',['confidential_information']])
    return make_information_bundle(xs)

def retention_information(t):
    xs=[]
    if 'copy' in t or 'copies' in t or 'backup system' in t:
        xs.append(['copies_of',['confidential_information']])
    if any_phrase(t,['notes or abstracts','notes and abstracts','compilation','analysis','derivative work']):
        xs.append(['derivative_materials_of',['confidential_information']])
    if not xs:
        xs.append(['confidential_information'])
    return make_information_bundle(xs)

def disposal_trigger(t):
    xs=[]
    if 'termination of service' in t or 'service terminates' in t:
        xs.append(['service_termination'])
    elif any_phrase(t,['upon termination of this agreement','upon termination of the agreement','termination of this agreement']):
        xs.append(['agreement_termination'])
    if 'completion of the purpose' in t:
        xs.append(['purpose_completion'])
    if (('upon' in t and 'request' in t) or 'receipt of a written request' in t or 'written request from' in t or 'written request of' in t):
        xs.append(['request_by',['disclosing_party']])
    if not xs:
        return None
    v=xs[0]
    i=1
    while i<len(xs):
        v=['trigger_alternative',v,xs[i]]
        i+=1
    return v

def retention_condition_for(t):
    if 'required' in t and 'applicable law' in t:
        return ['retention_condition','record copy required by applicable law']
    if 'archival purpose' in t:
        return ['retention_condition','one copy solely for archival purpose']
    if 'single copy' in t and any_phrase(t,['regulatory compliance','compliance with the terms']):
        return ['retention_condition','single copy for regulatory and agreement compliance']
    if 'single copy' in t:
        return ['retention_condition','single copy for the source-stated purpose']
    return ['retention_condition','source-stated limited retention']

def parse_disposal(raw,ids,out):
    t=raw.casefold()
    if not t:
        return
    actor=['named_recipient','Volunteer'] if 'volunteer' in t else ['receiving_party']
    explicit_retention=any_phrase(t,['may retain','may maintain a single copy'])
    cond=retention_condition_for(t)
    if explicit_retention:
        add_statement(out,['retention_permission',actor,retention_information(t),['after_disposal'],cond],ids)
    if 'retained' in t and any_phrase(t,['no copies','no copy','no copies, electronic or otherwise']):
        add_statement(out,['retention_prohibition',actor,retention_information(t),['after_disposal']],ids)
    trigger=disposal_trigger(t)
    if trigger is None:
        return
    do_return=re.search(r'\breturn(?:ed|ing)?\b',t,re.I) is not None
    do_destroy=re.search(r'\bdestroy(?:ed|ing)?\b',t,re.I) is not None and 'not destroyed' not in t
    if not do_return and not do_destroy:
        return
    info=disposal_information(t)
    if do_return and do_destroy:
        action=['action_alternative',['return_to',info,['disclosing_party']],['destroy',info]]
    elif do_return:
        action=['return_to',info,['disclosing_party']]
    else:
        action=['destroy',info]
    es=[]
    if 'unless otherwise instructed in writing' in t:
        es.append(['authorization_exception','different written instructions from the disclosing participant'])
    if explicit_retention:
        es.append(['retention_exception',actor,retention_information(t),cond])
    if not es:
        exceptions=['no_exceptions']
    else:
        exceptions=['exception_set',es[0]]
        i=1
        while i<len(es):
            exceptions=['add_exception',exceptions,es[i]]
            i+=1
    add_statement(out,['disposal_obligation',actor,action,trigger,exceptions],ids)

def _dr_candidate(text):
    t=text.casefold()
    return any_phrase(t,['return','destroy','retain','retention','no copies','no copy'])

def _dr_queries(spans):
    qs=[]
    i=0
    while i<len(spans):
        s=spans[i]
        raw=s.get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        if _dr_candidate(raw):
            unit_ids=[]
            if i>0:
                prev=spans[i-1]
                pr=prev.get('text','')
                if not isinstance(pr,str):
                    pr=str(pr)
                if pr.strip().endswith(':'):
                    unit_ids.append(prev.get('id'))
            unit_ids.append(s.get('id'))
            qs.append({'id':'disp_'+str(len(qs)),'operation':'disposal_retention_clause_role','unit_ids':unit_ids})
        i+=1
    return qs

def _dr_window(spans,unit_ids):
    texts=[]
    found=[]
    for wanted in unit_ids:
        for s in spans:
            if s.get('id')==wanted:
                raw=s.get('text','')
                if not isinstance(raw,str):
                    raw=str(raw)
                texts.append(raw)
                found.append(wanted)
                break
    return ' '.join(texts),found

def _dr_add_filtered(statements,temp,allowed):
    found=[]
    for s in temp:
        term=s.get('term')
        if isinstance(term,list) and term and term[0] in allowed:
            add_statement(statements,term,s.get('support_ids',[]))
            if term[0] not in found:
                found.append(term[0])
    return found
"}, "training": [{"source": "ContractNLI:354623271a5433b9d6fe42ec70538acd25e9f7e37aee568c81e2e7d4912f9450", "current_source_units": [{"id": 0, "field": "source_text", "start": 0, "end": 287, "text": "Non Disclosure Agreement Purpose The purpose of this policy is to ensure that those who volunteer their time in service to the Certification Council for Professional Dog Trainers agree to maintain in confidence anything they learn about the CCPDT’s examinations, processes or procedures.", "public_sentence_id": 0}, {"id": 3, "field": "source_text", "start": 288, "end": 413, "text": "Policy Annually the volunteers of the Certification Council for Professional Dog Trainers shall sign the following agreement:", "public_sentence_id": 3}, {"id": 5, "field": "source_text", "start": 414, "end": 667, "text": "In consideration for receiving certain confidential information in connection with providing services to or on behalf of the Certification Council for Professional Dog Trainers (CCPDT), I, herein referred to as “Volunteer”, hereby agree and acknowledge:", "public_sentence_id": 5}, {"id": 6, "field": "source_text", "start": 668, "end": 1446, "text": "Confidential and Proprietary Information For purposes of this Agreement, “Confidential Information” means all information and materials, in whatever form, whether tangible or intangible, disclosed by the Certification Council for Professional Dog Trainers or any of its authorized representatives to Volunteer, or to which Volunteer otherwise gains access as a result of volunteering for the Certification Council for Professional Dog Trainers, pertaining in any manner to the activities of the Certification Council for Professional Dog Trainers or its affiliates, consultants, members, or any person or entity to which the Certification Council for Professional Dog Trainers owes a duty of confidentiality, whether or not labeled or identified as proprietary or confidential.", "public_sentence_id": 6}, {"id": 8, "field": "source_text", "start": 1446, "end": 1604, "text": "All proprietary information of the Certification Council for Professional Dog Trainers that is not known generally to the public is Confidential Information.", "public_sentence_id": 8}, {"id": 9, "field": "source_text", "start": 1604, "end": 1704, "text": "Without limiting the generality of the foregoing, the following are deemed Confidential Information:", "public_sentence_id": 9}, {"id": 10, "field": "source_text", "start": 1705, "end": 1742, "text": " Ideas for research and development;", "public_sentence_id": 10}, {"id": 11, "field": "source_text", "start": 1743, "end": 1828, "text": " Information submitted in the investigation of complaints or involving ethics cases;", "public_sentence_id": 11}, {"id": 12, "field": "source_text", "start": 1829, "end": 1919, "text": " Computer records and software (including software that is proprietary to third parties);", "public_sentence_id": 12}, {"id": 13, "field": "source_text", "start": 1920, "end": 2073, "text": " Any other information which the Certification Council for Professional Dog Trainers must keep confidential as a result of obligations to third parties;", "public_sentence_id": 13}, {"id": 14, "field": "source_text", "start": 2074, "end": 2161, "text": " Information regarding the administration of components of the certification programs;", "public_sentence_id": 14}, {"id": 15, "field": "source_text", "start": 2162, "end": 2205, "text": " Exam-related technologies and components;", "public_sentence_id": 15}, {"id": 16, "field": "source_text", "start": 2206, "end": 2342, "text": " Item content, characteristics, development or other aspects of the examinations and their development, maintenance and administration;", "public_sentence_id": 16}, {"id": 17, "field": "source_text", "start": 2343, "end": 2514, "text": " Identities of Certificants, candidates, customers, suppliers, or third party contractors, including without limitation any media, advertising, or public relations firms;", "public_sentence_id": 17}, {"id": 18, "field": "source_text", "start": 2515, "end": 2602, "text": " The Certification Council for Professional Dog Trainers’ e-mail distribution list(s);", "public_sentence_id": 18}, {"id": 19, "field": "source_text", "start": 2603, "end": 2692, "text": " Human resources data and information about employees, contractors and other volunteers;", "public_sentence_id": 19}, {"id": 20, "field": "source_text", "start": 2693, "end": 2725, "text": " Cost and other financial data;", "public_sentence_id": 20}, {"id": 21, "field": "source_text", "start": 2726, "end": 2764, "text": " Polling and focus group information;", "public_sentence_id": 21}, {"id": 22, "field": "source_text", "start": 2765, "end": 2888, "text": " Any goods or services Volunteer provides to the Certification Council for Professional Dog Trainers under this Agreement.", "public_sentence_id": 22}, {"id": 23, "field": "source_text", "start": 2889, "end": 3029, "text": " Any other information to which Volunteer has access while involved in the Certification Council for Professional Dog Trainers’ activities.", "public_sentence_id": 23}, {"id": 24, "field": "source_text", "start": 3030, "end": 3277, "text": "Non-Disclosure  Volunteer agrees not to, without prior written consent from the Certification Council for Professional Dog Trainers, divulge any Confidential Information to third parties or copy documents containing any Confidential Information.", "public_sentence_id": 24}, {"id": 26, "field": "source_text", "start": 3277, "end": 3436, "text": "In no event shall Volunteer use Confidential Information in a manner that is in any way detrimental to the Certification Council for Professional Dog Trainers.", "public_sentence_id": 26}, {"id": 27, "field": "source_text", "start": 3437, "end": 3839, "text": " Volunteer agrees to maintain the confidentiality of all Confidential Information and not misuse, misappropriate, or disclose in writing, orally or by electronic means, any Confidential Information, directly or indirectly, to any other person or use them in any way, either during the term of this Agreement or at any other time thereafter, except as is required in the course of service to the CCPDT.", "public_sentence_id": 27}, {"id": 28, "field": "source_text", "start": 3840, "end": 4237, "text": " Volunteer acknowledges and agrees that all Confidential Information and similar items whether maintained in hard copy, electronically or on-line relating to CCPDT’s business shall remain exclusively the property of the Certification Council for Professional Dog Trainers and shall only be used by Volunteer for the purpose(s) permitted by the Certification Council for Professional Dog Trainers.", "public_sentence_id": 28}, {"id": 29, "field": "source_text", "start": 4238, "end": 4660, "text": " Volunteer further agrees that upon termination of service with CCPDT, Volunteer shall return within ten (10) business days all documents, files, electronic or otherwise, and property comprising Confidential Information of CCPDT and all copies, electronic or otherwise, thereof relating in any way to the Certification Council for Professional Dog Trainers’ business, or in any way obtained during the course of service.", "public_sentence_id": 29}, {"id": 30, "field": "source_text", "start": 4660, "end": 4836, "text": "Volunteer further agrees that no copies, electronic or otherwise, notes or abstracts of the foregoing shall be retained and that all information will be returned not destroyed.", "public_sentence_id": 30}, {"id": 31, "field": "source_text", "start": 4837, "end": 4997, "text": "Volunteer Conflict of Interest  Volunteers shall avoid personal and professional conflicts of interest in all matters pertaining to the Certification program.", "public_sentence_id": 31}, {"id": 33, "field": "source_text", "start": 4997, "end": 5137, "text": "Conflicting interests may include but are not limited to such areas as financial, personal relationships, and/or professional relationships.", "public_sentence_id": 33}, {"id": 34, "field": "source_text", "start": 5138, "end": 5397, "text": " If a situation arises where it is unclear as to whether a conflict of interest exists, Volunteer shall discuss the issue with the President of the Certification Council for Professional Dog Trainers (or the Vice President if the Volunteer is the President).", "public_sentence_id": 34}, {"id": 35, "field": "source_text", "start": 5398, "end": 5584, "text": " Depending on the type of volunteer work required from the individual, a volunteer may be asked to sign the CCPDT Conflict of Interest Policy prior to commencing service with the CCPDT.", "public_sentence_id": 35}, {"id": 36, "field": "source_text", "start": 5585, "end": 5800, "text": "Volunteer Code of Conduct  Volunteers shall act fairly and be impartial and unbiased in their service to the Certification Council for Professional Dog Trainers and to the population of Certificants and candidates.", "public_sentence_id": 36}, {"id": 38, "field": "source_text", "start": 5801, "end": 5969, "text": " Volunteers shall conduct themselves in a professional manner during the conduct of certification business and shall treat all stakeholders with courtesy and respect.", "public_sentence_id": 38}, {"id": 39, "field": "source_text", "start": 5969, "end": 6124, "text": "Volunteers shall not speak or act on behalf of the Certification Council for Professional Dog Trainers without proper written authorization from the CCPDT.", "public_sentence_id": 39}, {"id": 40, "field": "source_text", "start": 6125, "end": 6225, "text": " Volunteers shall support the decisions of the Certification Council for Professional Dog Trainers.", "public_sentence_id": 40}, {"id": 41, "field": "source_text", "start": 6226, "end": 6400, "text": " Volunteers shall participate in the activities required of them to fulfill their charge(s) and serve the mission of the Certification Council for Professional Dog Trainers.", "public_sentence_id": 41}, {"id": 42, "field": "source_text", "start": 6401, "end": 6498, "text": " Volunteers shall be an advocate for the CCPDT’s certification programs and support its mission.", "public_sentence_id": 42}, {"id": 43, "field": "source_text", "start": 6499, "end": 6755, "text": " Volunteers shall acknowledge that failure to uphold and abide by the Volunteer Code of Conduct may result in removal from participation in the certification program and volunteers shall willingly accept their termination as discussed in the next section.", "public_sentence_id": 43}, {"id": 44, "field": "source_text", "start": 6756, "end": 6900, "text": "Remedies  Violation of this Agreement will be grounds for termination of service with the Certification Council for Professional Dog Trainers.", "public_sentence_id": 44}, {"id": 46, "field": "source_text", "start": 6900, "end": 7010, "text": "A Committee Chair plus any two members of the Executive Committee may elect to remove a volunteer at any time.", "public_sentence_id": 46}, {"id": 47, "field": "source_text", "start": 7011, "end": 7273, "text": " The provisions of this Agreement and Volunteer’s obligations hereunder shall survive any expiration, termination, or rescission of this Agreement and remain even after Volunteer’s relationship with the Certification Council for Professional Dog Trainers ends.", "public_sentence_id": 47}, {"id": 48, "field": "source_text", "start": 7273, "end": 7485, "text": "Except as provided herein, Volunteer is prohibited from disclosing or using any confidential information in all circumstances, including but not limited to subsequent engagements or employment with third parties.", "public_sentence_id": 48}, {"id": 49, "field": "source_text", "start": 7486, "end": 7676, "text": " This Agreement shall be binding upon Volunteer and Volunteer’s personal representatives and successors in interest, and shall inure to the benefit of the CCPDT, its successors and assigns.", "public_sentence_id": 49}, {"id": 50, "field": "source_text", "start": 7677, "end": 7919, "text": " Volunteer acknowledges that a violation of the terms of this Agreement may cause damage and harm to CCPDT and that any such damage or harm will be difficult if not impossible to calculate in monetary terms and will be irreparable to CCPDT.", "public_sentence_id": 50}, {"id": 51, "field": "source_text", "start": 7919, "end": 8130, "text": "Volunteer agrees that, upon notice from CCPDT declaring a breach of this Agreement, Volunteer shall immediately cease all further activities which are, or are claimed by CCPDT to be, a breach of this Agreement.", "public_sentence_id": 51}, {"id": 52, "field": "source_text", "start": 8130, "end": 8247, "text": "The Certification Council for Professional Dog Trainers may also avail itself of any other remedies available by law.", "public_sentence_id": 52}, {"id": 53, "field": "source_text", "start": 8248, "end": 8518, "text": " If any of the provisions of this Agreement are found to be unenforceable, the remainder shall be enforced as fully as possible and the unenforceable provision(s) shall be deemed modified to the limited extent required to permit enforcement of the Agreement as a whole.", "public_sentence_id": 53}, {"id": 54, "field": "source_text", "start": 8519, "end": 8523, "text": "By:", "public_sentence_id": 54}, {"id": 55, "field": "source_text", "start": 8523, "end": 8740, "text": "____________________________________________________________________________________ Volunteer Signature _______________________________________________________________________________________ Volunteer’s Name (Print)", "public_sentence_id": 55}], "tasks": {"nda-5": {"question": "Receiving Party may share some Confidential Information with some of Receiving Party's employees.", "native_annotation": {"answer": "NotMentioned", "evidence": null}}, "nda-7": {"question": "Receiving Party may share some Confidential Information with some third-parties (including consultants, agents and professional advisors).", "native_annotation": {"answer": "Contradiction", "evidence": [25]}}, "nda-16": {"question": "Receiving Party shall destroy or return some Confidential Information upon the termination of Agreement.", "native_annotation": {"answer": "Entailment", "evidence": [29]}}, "nda-20": {"question": "Receiving Party may retain some Confidential Information even after the return or destruction of Confidential Information.", "native_annotation": {"answer": "Contradiction", "evidence": [30]}}}}, {"source": "ContractNLI:d9360f2a8c03efc35524289167a83e9505ebae476367505b868af29f37fcffa0", "current_source_units": [{"id": 0, "field": "source_text", "start": 0, "end": 474, "text": "MUTUAL NON-DISCLOSURE AGREEMENT THIS AGREEMENT is made the __ day of _____________ in the year 2016 by and between Switchdigital (London) Limited (with Registration Number 03729042) whose registered office is at 18 Hatfields, London SE1 8DJ ("Switchdigital") and COMPANY NAME ________________________________ ("Applicant") REGISTRATION NUMBER ________________________________ REGISTERED OFFICE is at ________________________________ ________________________________ WHEREAS:", "public_sentence_id": 0}, {"id": 12, "field": "source_text", "start": 475, "end": 823, "text": "(A) The parties, for their mutual benefit, may have exchanged and wish further to exchange certain information (including but not limited to trade secrets and proprietary know-how) in order that each of them may evaluate such information for the purpose of determining their respective interest in establishing a business relationship between them.", "public_sentence_id": 12}, {"id": 13, "field": "source_text", "start": 824, "end": 991, "text": "(B) The parties wish to define their rights with respect to the said information and to protect the confidentiality thereof and proprietary features contained therein.", "public_sentence_id": 13}, {"id": 14, "field": "source_text", "start": 992, "end": 1027, "text": "NOW IT IS HEREBY AGREED AS FOLLOWS:", "public_sentence_id": 14}, {"id": 15, "field": "source_text", "start": 1028, "end": 1120, "text": "1 Definitions In this Agreement the following expressions shall have the following meanings:", "public_sentence_id": 15}, {"id": 17, "field": "source_text", "start": 1121, "end": 1431, "text": "(a) 'Purpose' shall mean any discussions, negotiations and development work undertaken between or within the parties concerning or in connection with Switchdigital and the Applicant entering into a carriage agreement for carriage of the Applicant’s radio service on the DAB multiplex operated by Switchdigital;", "public_sentence_id": 17}, {"id": 18, "field": "source_text", "start": 1432, "end": 2166, "text": "(b) 'Confidential Information' shall mean all information or data disclosed (whether in writing, orally or by any other means) to one party by the other party or by a third party on behalf of the other party and shall include but not be limited to (A) any information ascertainable by the inspection or analysis of samples, (B) the information described in the Schedule 1 hereto as having been disclosed prior to the date hereof and (C) any information relating to that party's business, operations, prices, processes, plans, intentions, product information, know-how, design rights, trade secrets, software, market opportunities, customers and business affairs, but shall exclude any part of such disclosed information or data which:", "public_sentence_id": 18}, {"id": 22, "field": "source_text", "start": 2167, "end": 2276, "text": "(i) is or becomes in the public domain in any way without breach of this Agreement by the receiving party; or", "public_sentence_id": 22}, {"id": 23, "field": "source_text", "start": 2277, "end": 2603, "text": "(ii) the receiving party can show (A) was in its possession or known to it by being in its use or being recorded in its files or computers or other recording media prior to receipt from the disclosing party and was not previously acquired by the receiving party from the disclosing party under an obligation of confidence; or", "public_sentence_id": 23}, {"id": 25, "field": "source_text", "start": 2603, "end": 2748, "text": "(B) to have been developed by or for the receiving party at any time independently of the information disclosed to it by the disclosing party; or", "public_sentence_id": 25}, {"id": 26, "field": "source_text", "start": 2749, "end": 2998, "text": "(iii) is hereafter disclosed or made available to the receiving party from a source other than the disclosing party without breach by the receiving party or such source of any obligation of confidentiality or non-use towards the disclosing party; or", "public_sentence_id": 26}, {"id": 27, "field": "source_text", "start": 2999, "end": 3268, "text": "(iv) is hereafter made generally available by the disclosing party or a third party or is disclosed by the disclosing party to a third party without restriction on disclosure or use, including, without limitation, by way of the publication of a patent specification; or", "public_sentence_id": 27}, {"id": 28, "field": "source_text", "start": 3269, "end": 3365, "text": "(v) is disclosed by the receiving party with the prior written approval of the disclosing party;", "public_sentence_id": 28}, {"id": 29, "field": "source_text", "start": 3366, "end": 3732, "text": "provided however that the foregoing exceptions shall not apply to information relating to any combination of features or any combination of items of information merely because information relating to one or more of the relevant individual features or one or more of the relevant items (but not the combination itself) falls within any one or more of such exceptions.", "public_sentence_id": 29}, {"id": 30, "field": "source_text", "start": 3733, "end": 3936, "text": "2 Handling of confidential information In consideration of the mutual exchange and disclosure of Confidential Information, each party undertakes in relation to the other party's Confidential Information:", "public_sentence_id": 30}, {"id": 32, "field": "source_text", "start": 3937, "end": 4615, "text": "(a) to maintain the same in confidence and to use it only for the Purpose and for no other purpose and in particular, but without prejudice to the generality of the foregoing, (i) not to make any commercial use thereof (ii) not to use the same for the benefit of itself or of any third party other than pursuant to a further agreement with the other party and (iii) not to use the same for the purpose of guiding or conducting a search of any information, materials or sources, whether or not available to the public, for any purpose whatsoever, including, without limitation, for the purpose of demonstrating that any information falls within one of the exceptions in clause 1;", "public_sentence_id": 32}, {"id": 36, "field": "source_text", "start": 4616, "end": 4847, "text": "(b) not to copy reproduce or reduce to writing any part thereof except as may be reasonably necessary for the Purpose and that any copies reproductions or reductions to writing so made shall be the property of the disclosing party;", "public_sentence_id": 36}, {"id": 37, "field": "source_text", "start": 4848, "end": 5375, "text": {"__lsg_shared_value__": "v0"}, "public_sentence_id": 37}, {"id": 40, "field": "source_text", "start": 5376, "end": 5564, "text": "(d) to be responsible for the performance of sub-clause (a), (b) and (c) above on the part of its employees or directors to whom the same is disclosed pursuant to sub-clause (c) above; and", "public_sentence_id": 40}, {"id": 45, "field": "source_text", "start": 5565, "end": 5866, "text": "(e) to apply thereto no lesser security measures and degree of care than those which the receiving party applies to its own confidential or proprietary information and which the receiving party warrants as providing adequate protection of such information from unauthorised disclosure, copying or use.", "public_sentence_id": 45}, {"id": 46, "field": "source_text", "start": 5867, "end": 6241, "text": "Notwithstanding the foregoing, the receiving party shall be entitled to make any disclosure required by law of the other party's Confidential Information, but shall give the other party not less than two business days' notice of such disclosure and shall consult with the disclosing party prior to such disclosure with a view to avoiding such disclosure if legally possible.", "public_sentence_id": 46}, {"id": 47, "field": "source_text", "start": 6242, "end": 6296, "text": "3 Return of confidential information Each party shall:", "public_sentence_id": 47}, {"id": 50, "field": "source_text", "start": 6297, "end": 6642, "text": {"__lsg_shared_value__": "v2"}, "public_sentence_id": 50}, {"id": 51, "field": "source_text", "start": 6643, "end": 6801, "text": "(b) notwithstanding completion of the Purpose or return of documents and materials as aforesaid, continue to be bound by the undertakings set out in clause 2.", "public_sentence_id": 51}, {"id": 52, "field": "source_text", "start": 6802, "end": 7016, "text": "4 Disclaimer and warranty (a) Each party reserves all rights in its Confidential Information and no rights or obligations other than those expressly recited herein are granted or to be implied from this Agreement.", "public_sentence_id": 52}, {"id": 54, "field": "source_text", "start": 7016, "end": 7240, "text": "In particular, no licence is hereby granted directly or indirectly under any patent, invention, discovery, copyright or other industrial property right now or in the future held, made, obtained or licensable by either party.", "public_sentence_id": 54}, {"id": 55, "field": "source_text", "start": 7241, "end": 7400, "text": "(b) Each party warrants its right to disclose its Confidential Information to the other party and to authorise the other party to use the same for the Purpose.", "public_sentence_id": 55}, {"id": 56, "field": "source_text", "start": 7401, "end": 7779, "text": "5 Confidentiality Each party agrees to keep the existence and nature of this Agreement confidential and not to use the same or the name of the other party (or of any other company in the Group of Companies of which the other party forms part) in any publicity, advertisement or other disclosure with regard to this Agreement without the prior written consent of the other party.", "public_sentence_id": 56}, {"id": 58, "field": "source_text", "start": 7780, "end": 8127, "text": "6 Notices All notices under this Agreement shall be in writing and shall be sent by first-class registered or recorded delivery post to the party being served at its address specified above or at such other address of which such party shall have given notice as aforesaid, and marked for the attention of that party's signatory of this Agreement.", "public_sentence_id": 58}, {"id": 60, "field": "source_text", "start": 8127, "end": 8260, "text": "The date of service shall be deemed to be the day following the day on which the notice was transmitted or posted as the case may be.", "public_sentence_id": 60}, {"id": 61, "field": "source_text", "start": 8261, "end": 8391, "text": "7 Term and Termination This Agreement shall become effective from the date hereof and continue in force for a period of one year.", "public_sentence_id": 61}, {"id": 63, "field": "source_text", "start": 8391, "end": 8463, "text": "The provisions of clauses 1, 2 and 3 shall survive any such termination.", "public_sentence_id": 63}, {"id": 64, "field": "source_text", "start": 8464, "end": 8663, "text": "8 Non-assignment This Agreement is personal to the parties and shall not be assigned or otherwise transferred in whole or in part by either party without the prior written consent of the other party.", "public_sentence_id": 64}, {"id": 66, "field": "source_text", "start": 8664, "end": 8948, "text": "9 Severability If any provision of this Agreement is found by any court of competent jurisdiction to be invalid or unenforceable, the invalidity or unenforceability of such provision shall not affect the other provisions of this Agreement which shall remain in full force and effect.", "public_sentence_id": 66}, {"id": 68, "field": "source_text", "start": 8948, "end": 9117, "text": "Where relevant, the parties shall use their reasonable endeavours to find a new stipulation resembling the invalid one in its commercial consequence as much as possible.", "public_sentence_id": 68}, {"id": 69, "field": "source_text", "start": 9118, "end": 9285, "text": "10 Equitable Relief Both parties to this Agreement acknowledge that the Confidential Information belonging to each party is a unique and valuable asset of such party.", "public_sentence_id": 69}, {"id": 71, "field": "source_text", "start": 9285, "end": 9446, "text": "Disclosure in breach of this Agreement will result in irreparable injury to the disclosing party for which monetary damages alone will not be an adequate remedy.", "public_sentence_id": 71}, {"id": 72, "field": "source_text", "start": 9447, "end": 9752, "text": "Therefore, the parties agree that in the event of a breach or threatened breach of the terms of this Agreement, the disclosing party will be entitled to specific performance, injunctive relief or other equitable relief prohibiting any breach of this Agreement without giving an undertaking as to damages.", "public_sentence_id": 72}, {"id": 73, "field": "source_text", "start": 9752, "end": 9900, "text": "Any such equitable remedy shall be in addition to and not in lieu of, other appropriate relief at law to which the disclosing party may be entitled.", "public_sentence_id": 73}, {"id": 74, "field": "source_text", "start": 9901, "end": 10114, "text": "11 Counterparts This Agreement may be signed in any number of counterparts and/or via email through the exchange of scanned pdf copies with the same effect as if the signature to each were upon the same Agreement.", "public_sentence_id": 74}, {"id": 76, "field": "source_text", "start": 10115, "end": 10390, "text": "12 No Partnership This Agreement is neither intended to nor will it be construed as creating a joint venture, partnership or other form of business association between the parties, nor an obligation to buy or sell products using or incorporating the Confidential Information.", "public_sentence_id": 76}, {"id": 78, "field": "source_text", "start": 10391, "end": 10665, "text": "13 No Waiver The failure of either party to enforce any rights resulting from any breach of any term or provision of this Agreement by the other party will not be deemed a waiver of any right relating to a subsequent breach of such provision or of any other right hereunder.", "public_sentence_id": 78}, {"id": 80, "field": "source_text", "start": 10666, "end": 11046, "text": "14 Entire agreement, governing law and jurisdiction This Agreement constitutes the entire Agreement and understanding between the parties in respect of Confidential Information and supersedes all previous agreements, understandings and undertakings in such respect and all obligations implied by law to the extent that they conflict with the express provisions of this Agreement.", "public_sentence_id": 80}, {"id": 82, "field": "source_text", "start": 11046, "end": 11128, "text": "This Agreement cannot be changed except by written agreement between the parties.", "public_sentence_id": 82}, {"id": 83, "field": "source_text", "start": 11128, "end": 11356, "text": "The interpretation construction and effect of this Agreement shall be governed and construed in all respects in accordance with English Law and the parties submit to the exclusive jurisdiction of the courts of England and Wales.", "public_sentence_id": 83}, {"id": 84, "field": "source_text", "start": 11357, "end": 11498, "text": "AS WITNESS this Agreement has been signed on behalf of each party by its duly authorized representative the day and year first above written.", "public_sentence_id": 84}, {"id": 85, "field": "source_text", "start": 11499, "end": 11579, "text": "SIGNED for & on behalf of: Switchdigital (London) Limited Authorised Signatory:", "public_sentence_id": 85}, {"id": 87, "field": "source_text", "start": 11579, "end": 11671, "text": "_____________________________ Name: Piers Collins Title: Director SIGNED for & on behalf of:", "public_sentence_id": 87}, {"id": 91, "field": "source_text", "start": 11672, "end": 11694, "text": "Authorised Signatory:", "public_sentence_id": 91}, {"id": 92, "field": "source_text", "start": 11694, "end": 11729, "text": "_____________________________ Name:", "public_sentence_id": 92}, {"id": 94, "field": "source_text", "start": 11730, "end": 11736, "text": "Title:", "public_sentence_id": 94}, {"id": 95, "field": "source_text", "start": 11737, "end": 11805, "text": "SCHEDULE 1 INFORMATION DISCLOSED PRIOR TO THE DATE OF THIS AGREEMENT", "public_sentence_id": 95}], "tasks": {"nda-5": {"question": "Receiving Party may share some Confidential Information with some of Receiving Party's employees.", "native_annotation": {"answer": "Entailment", "evidence": [31, 37]}}, "nda-7": {"question": "Receiving Party may share some Confidential Information with some third-parties (including consultants, agents and professional advisors).", "native_annotation": {"answer": "Entailment", "evidence": [31, 37]}}, "nda-16": {"question": "Receiving Party shall destroy or return some Confidential Information upon the termination of Agreement.", "native_annotation": {"answer": "Entailment", "evidence": [49, 50]}}, "nda-20": {"question": "Receiving Party may retain some Confidential Information even after the return or destruction of Confidential Information.", "native_annotation": {"answer": "Contradiction", "evidence": [49, 50]}}}}, {"source": "ContractNLI:442c36c12745965b79f777dedc7bc3dc249d80ca444c395ece6ec7953c15c07f", "current_source_units": [{"id": 0, "field": "source_text", "start": 0, "end": 400, "text": "Mutual Non-Disclosure and Use of Information Agreement to Support Emergency Cyber Mutual Assistance This Non-Disclosure and Use of Information Agreement (the "Agreement'') is made and entered into as of this 15th day of June, 2016 by and among each entity that executes and delivers the signature page to this Agreement (each, a "Participating Entity" and collectively, the "Participating Entities").", "public_sentence_id": 0}, {"id": 3, "field": "source_text", "start": 401, "end": 724, "text": "A. Each Participating Entity is participating in a voluntary effort to assist the Electricity Subsector Coordinating Council (ESCC) in developing and implementing one or more industry initiatives to provide cyber emergency assistance to entities in the electric sector (collectively, the “Cyber Mutual Assistance Program”).", "public_sentence_id": 3}, {"id": 5, "field": "source_text", "start": 725, "end": 959, "text": "B. In connection with the Cyber Mutual Assistance Program, each Participating Entity may voluntarily choose to request from or provide to another Participating Entity emergency cyber mutual assistance in response to a cyber emergency;", "public_sentence_id": 5}, {"id": 6, "field": "source_text", "start": 960, "end": 1212, "text": "C. The development and implementation of any Cyber Mutual Assistance Program, including any request or provision of cyber mutual assistance between Participating Entities, may necessitate the exchange of certain confidential or proprietary information.", "public_sentence_id": 6}, {"id": 7, "field": "source_text", "start": 1213, "end": 1333, "text": "NOW, THEREFORE, in consideration of the mutual covenants in this Agreement, the Participating Entities agree as follows:", "public_sentence_id": 7}, {"id": 8, "field": "source_text", "start": 1334, "end": 1370, "text": "1. Purpose, Scope, and Definitions.", "public_sentence_id": 8}, {"id": 9, "field": "source_text", "start": 1370, "end": 1776, "text": "The purpose of this Agreement is to permit each Participating Entity to exchange Confidential Information (as defined below) as needed to pursue the development and implementation of a Cyber Mutual Assistance Program, including any request for or provision of cyber mutual assistance between Participating Entities in response to a cyber emergency or in connection with any Cyber Mutual Assistance Program.", "public_sentence_id": 9}, {"id": 10, "field": "source_text", "start": 1777, "end": 1837, "text": "“Confidential Information” under this Agreement consists of:", "public_sentence_id": 10}, {"id": 11, "field": "source_text", "start": 1838, "end": 2337, "text": "(i) all information disclosed by any Participating Entity, or any of its employees, directors, officers, affiliates, partners, agents, advisors or other representatives (“Representatives”) pursuant to that Participating Entity’s participation in or contribution to the development or implementation of a Cyber Mutual Assistance Program, including any Participating Entity’s request for or provision of cyber mutual assistance, whether disclosed prior to or following the execution of this Agreement;", "public_sentence_id": 11}, {"id": 12, "field": "source_text", "start": 2338, "end": 2681, "text": "(ii) any information or documentation produced by a Participating Entity, or any of its Representatives, under any Cyber Mutual Assistance Program or related to a specific request for or response to cyber mutual assistance, including any analysis of such information, and whether produced prior to or following the execution of this Agreement;", "public_sentence_id": 12}, {"id": 13, "field": "source_text", "start": 2682, "end": 3032, "text": "(iii) any aggregation, consolidation, or listing of information or documentation disclosed by one or more Participating Entities, or any of their respective Representatives, pursuant to the development or implementation of a Cyber Mutual Assistance Program including any Participating Entity’s request for or provision of cyber mutual assistance; and", "public_sentence_id": 13}, {"id": 14, "field": "source_text", "start": 3033, "end": 3440, "text": "(iv) all observations of equipment (including computer screens) and oral disclosures related to the development of any Cyber Mutual Assistance Program or a specific request for or response to cyber mutual assistance, including the systems, operations, and activities of each Participating Entity, whether such observations or oral disclosures were made prior to or following the execution of this Agreement.", "public_sentence_id": 14}, {"id": 15, "field": "source_text", "start": 3441, "end": 3496, "text": "2. Non-Disclosure and Use of Confidential Information.", "public_sentence_id": 15}, {"id": 16, "field": "source_text", "start": 3496, "end": 3996, "text": "Each Participating Entity agrees (i) to maintain the confidentiality of all Confidential Information obtained, (ii) without the express permission of the Participating Entity providing such information, not to disclose such information to third parties, and (iii) to use such information only for the express purpose of developing and implementing a Cyber Mutual Assistance Program, including in connection with any request for or provision of cyber mutual assistance between Participating Entities.", "public_sentence_id": 16}, {"id": 21, "field": "source_text", "start": 3996, "end": 4127, "text": "Each Participating Entity shall use the Confidential Information received hereunder only for the purposes identified in Section 1.", "public_sentence_id": 21}, {"id": 23, "field": "source_text", "start": 4127, "end": 4402, "text": "Notwithstanding the forgoing, a Participating Entity may use and internally share Confidential Information as deemed necessary to respond to an actual or threatened cyber emergency that places, or has the potential to place, the Participating Entity’s cyber systems at risk.", "public_sentence_id": 23}, {"id": 24, "field": "source_text", "start": 4402, "end": 4576, "text": "Any other use shall be only with the prior written consent of the Participating Entity or Participating Entities that provided the Confidential Information sought to be used.", "public_sentence_id": 24}, {"id": 25, "field": "source_text", "start": 4577, "end": 4610, "text": "3. Exemptions to Non-Disclosure.", "public_sentence_id": 25}, {"id": 26, "field": "source_text", "start": 4610, "end": 4823, "text": "Notwithstanding Sections 1 and 2, a Participating Entity shall not have breached any obligation under this Agreement if the Confidential Information is disclosed to a third party when the Confidential Information:", "public_sentence_id": 26}, {"id": 27, "field": "source_text", "start": 4824, "end": 5063, "text": "(a) was in the public domain at the time of such disclosure or is subsequently made available to the public by the Participating Entity who provided the Confidential Information, or otherwise consistent with the terms of this Agreement; or", "public_sentence_id": 27}, {"id": 28, "field": "source_text", "start": 5064, "end": 5285, "text": "(b) had been received or independently developed by such Participating Entity at or prior to the time of disclosure through a process other than the development or implementation of the Cyber Mutual Assistance Program; or", "public_sentence_id": 28}, {"id": 29, "field": "source_text", "start": 5286, "end": 5441, "text": "(c) is subsequently disclosed to the Participating Entity by a third party without restriction on use and without breach of any agreement or legal duty; or", "public_sentence_id": 29}, {"id": 30, "field": "source_text", "start": 5442, "end": 5746, "text": "(d) subject to the provisions of Section 4, is used or disclosed pursuant to statutory duty, such as a public records act request, or an order, subpoena, discovery request, or other lawful process issued by a court or other governmental authority of competent jurisdiction or in a judicial proceeding; or", "public_sentence_id": 30}, {"id": 31, "field": "source_text", "start": 5747, "end": 5900, "text": "(e) is disclosed by unanimous agreement of each of the Participating Entity or Participating Entities whose information is subject to such disclosure; or", "public_sentence_id": 31}, {"id": 32, "field": "source_text", "start": 5901, "end": 6174, "text": "(f) after the time of its disclosure hereunder, becomes subsequently available to such Participating Entity on a non-confidential basis from a source not known by such Participating Entity to be bound by a confidentiality agreement or secrecy obligation in respect thereof.", "public_sentence_id": 32}, {"id": 33, "field": "source_text", "start": 6175, "end": 6246, "text": "4. Notice of Pending Third-Party Disclosure or Unauthorized Disclosure.", "public_sentence_id": 33}, {"id": 34, "field": "source_text", "start": 6247, "end": 6653, "text": "(a) In the event that any governmental authority issues an order, subpoena, or other lawful process or a Participating Entity receives a discovery request in a civil proceeding ("Legal Process") requiring the disclosure of any Confidential Information, the Participating Entity receiving such Legal Process shall notify in writing the other Participating Entities within five (5) business days of receipt.", "public_sentence_id": 34}, {"id": 35, "field": "source_text", "start": 6653, "end": 6936, "text": "The Participating Entity receiving such Legal Process shall not be in violation of this Agreement if it complies with the Legal Process requiring disclosure of the Confidential Information after seven (7) business days following Participating Entity notification, as set forth above.", "public_sentence_id": 35}, {"id": 36, "field": "source_text", "start": 6937, "end": 7270, "text": "(b) A Participating Entity shall not disclose any Confidential Information in response to a request under the federal Freedom of Information Act, 5 U.S.C. § 552, as amended, or an equivalent state or local open records law, except as required by law as determined in the written opinion of such Participating Entity’s legal counsel.", "public_sentence_id": 36}, {"id": 37, "field": "source_text", "start": 7270, "end": 7386, "text": "Upon receipt of a Freedom of Information Act or public records disclosure request, such Participating Entity shall:", "public_sentence_id": 37}, {"id": 38, "field": "source_text", "start": 7386, "end": 7624, "text": "(i) notify each Participating Entity or Participating Entities whose information is subject to such disclosure request immediately upon receipt of a request for public records that include all or part of the Confidential Information; and", "public_sentence_id": 38}, {"id": 39, "field": "source_text", "start": 7624, "end": 7925, "text": "(ii) if, in the written opinion of the legal counsel for the Participating Entity receiving the information request, the Confidential Information is not legally required to be disclosed, treat the requested Confidential Information as exempt from disclosure to the extent permitted by applicable law.", "public_sentence_id": 39}, {"id": 40, "field": "source_text", "start": 7925, "end": 8192, "text": "The Participating Entity receiving the information request shall cooperate with the Participating Entity or Participating Entities whose information is subject to such disclosure request in challenging the request or seeking another appropriate remedy, as necessary.", "public_sentence_id": 40}, {"id": 41, "field": "source_text", "start": 8192, "end": 8472, "text": "If such challenge to the request is not successful and another remedy is not obtained, only that portion of the Confidential Information that is legally required to be disclosed, as determined in the written opinion of the Participating Entity’s legal counsel, shall be disclosed.", "public_sentence_id": 41}, {"id": 42, "field": "source_text", "start": 8473, "end": 8502, "text": "(c) Unauthorized Disclosure:", "public_sentence_id": 42}, {"id": 43, "field": "source_text", "start": 8502, "end": 9049, "text": "If a Participating Entity becomes aware that Confidential Information has been or likely has been disclosed to a third party in violation of this Agreement, the Participating Entity will immediately notify the Participating Entity in writing that provided the disclosed Confidential Information, provide a description of the information disclosed, and provide reasonable assistance to the Participating Entity that provided the disclosed Confidential Information to recover the Confidential Information and prevent further unauthorized disclosure.", "public_sentence_id": 43}, {"id": 44, "field": "source_text", "start": 9050, "end": 9059, "text": "5. Term.", "public_sentence_id": 44}, {"id": 45, "field": "source_text", "start": 9059, "end": 9571, "text": "This Agreement shall remain in effect as to each Participating Entity unless and until a Participating Entity seeking to withdraw from the agreement provides ten (10) days’ prior written notice to the other Participating Entities, then this Agreement shall terminate with respect to such Participating Entity at the conclusion of such ten (10) day period; provided, however, that termination shall not extinguish any claim, liability, or cause of action under this Agreement existing at the time of termination.", "public_sentence_id": 45}, {"id": 46, "field": "source_text", "start": 9571, "end": 9697, "text": "The provisions of Sections 1, 2, 3, 4, 5 and 6 shall survive the termination of this Agreement for a period of ten (10) years.", "public_sentence_id": 46}, {"id": 47, "field": "source_text", "start": 9698, "end": 9752, "text": "6. Return or Destruction of Confidential Information.", "public_sentence_id": 47}, {"id": 48, "field": "source_text", "start": 9752, "end": 10169, "text": "Upon termination of this Agreement, all Confidential Information in the possession or control of a Participating Entity and its Representatives that received such information shall be returned to the Participating Entity that disclosed the information, including all copies of such information in any form whatsoever, unless otherwise instructed in writing by the Participating Entity that disclosed the information.", "public_sentence_id": 48}, {"id": 49, "field": "source_text", "start": 10169, "end": 10442, "text": {"__lsg_shared_value__": "v4"}, "public_sentence_id": 49}, {"id": 50, "field": "source_text", "start": 10442, "end": 10627, "text": "In lieu of return, a Participating Entity may certify to the other Participating Entities in writing that all such Confidential Information, in any form whatsoever, has been destroyed.", "public_sentence_id": 50}, {"id": 51, "field": "source_text", "start": 10627, "end": 10809, "text": "Notwithstanding anything in this paragraph 6 to the contrary, a Participating Entity may retain a record copy of any Confidential Information if required to do so by applicable law.", "public_sentence_id": 51}, {"id": 52, "field": "source_text", "start": 10809, "end": 11154, "text": "In such an instance, such Participating Entity shall identify in writing the specific Confidential Information retained, and shall provide the affected Participating Entity or Participating Entities with a written commitment to return or destroy the retained Confidential Information upon the expiration of the retention period required by law.", "public_sentence_id": 52}, {"id": 53, "field": "source_text", "start": 11154, "end": 11400, "text": "The obligation under this Agreement to maintain the confidentiality of all Confidential Information shall continue to apply to such retained Confidential Information for so long as the Participating Entity possesses such Confidential Information.", "public_sentence_id": 53}, {"id": 54, "field": "source_text", "start": 11401, "end": 11413, "text": "7. Notices.", "public_sentence_id": 54}, {"id": 55, "field": "source_text", "start": 11413, "end": 12016, "text": "All notices, requests, demands, and other communications required or permitted under this Agreement shall be in writing, unless otherwise agreed by the Participating Entities, and shall be delivered in person or sent by certified mail, postage prepaid, by overnight delivery, or by electronic mail or electronic facsimile transmission with an original sent immediately thereafter by postage prepaid mail, and properly addressed with respect to a particular Participating Entity, to such Participating Entity’s representative as set forth on such Participating Entity’s signature page to this Agreement.", "public_sentence_id": 55}, {"id": 56, "field": "source_text", "start": 12016, "end": 12357, "text": "A Participating Entity may from time to time change its representative or address for the purpose of notices to that Participating Entity by a similar notice specifying a new representative or address, but no such change shall be deemed to have been given until such notice is actually received by the Participating Entity being so notified.", "public_sentence_id": 56}, {"id": 57, "field": "source_text", "start": 12358, "end": 12398, "text": "8. Complete Agreement; No Other Rights.", "public_sentence_id": 57}, {"id": 58, "field": "source_text", "start": 12398, "end": 12533, "text": "This Agreement contains the complete and exclusive agreement of the Participating Entities with respect to the subject matter thereof.", "public_sentence_id": 58}, {"id": 59, "field": "source_text", "start": 12533, "end": 12660, "text": "No change to this Agreement shall be effective unless agreed to in writing by all of the then existing Participating Entities.", "public_sentence_id": 59}, {"id": 60, "field": "source_text", "start": 12660, "end": 12812, "text": "This Agreement is not intended to create any right in or obligation of any Participating Entity or third party other than those expressly stated herein.", "public_sentence_id": 60}, {"id": 61, "field": "source_text", "start": 12813, "end": 12850, "text": "9. No Warranties or Representations.", "public_sentence_id": 61}, {"id": 62, "field": "source_text", "start": 12850, "end": 12988, "text": "Any Confidential Information disclosed under this Agreement carries no warranty or representation of any kind, either express or implied.", "public_sentence_id": 62}, {"id": 63, "field": "source_text", "start": 12988, "end": 13197, "text": "A Participating Entity receiving such Confidential Information shall not be entitled to rely on the accuracy, completeness, or quality of the Confidential Information, even for the purpose stated in Section 1.", "public_sentence_id": 63}, {"id": 64, "field": "source_text", "start": 13198, "end": 13221, "text": "10. Injunctive Relief.", "public_sentence_id": 64}, {"id": 65, "field": "source_text", "start": 13221, "end": 13600, "text": "Each Participating Entity agrees that, in addition to whatever other remedies may be available to the other Participating Entities under applicable law, the other Participating Entities shall be entitled to seek injunctive relief with respect to any actual or threatened violation of this Agreement by a Participating Entity or any third party receiving Confidential Information.", "public_sentence_id": 65}, {"id": 67, "field": "source_text", "start": 13601, "end": 13630, "text": "11. Choice of Law and Forum.", "public_sentence_id": 67}, {"id": 68, "field": "source_text", "start": 13630, "end": 13874, "text": "This Agreement shall be governed by and construed in accordance with the laws of the State of New York without giving effect to any choice or conflicts of law provision or rule that would cause the application of laws of any other jurisdiction.", "public_sentence_id": 68}, {"id": 69, "field": "source_text", "start": 13875, "end": 13891, "text": "12. Assignment.", "public_sentence_id": 69}, {"id": 70, "field": "source_text", "start": 13891, "end": 13987, "text": "This Agreement shall be binding upon the Participating Entities, their successors, and assigns.", "public_sentence_id": 70}, {"id": 71, "field": "source_text", "start": 13987, "end": 14107, "text": "No Participating Entity may assign this Agreement without the prior written consent of the other Participating Entities.", "public_sentence_id": 71}, {"id": 72, "field": "source_text", "start": 14108, "end": 14139, "text": "13. Construction of Agreement.", "public_sentence_id": 72}, {"id": 73, "field": "source_text", "start": 14139, "end": 14411, "text": "Ambiguities or uncertainties in the wording of this Agreement shall not be construed for or against any Participating Entity, but shall be construed in the manner that most accurately reflects the Participating Entities’ intent as of the date they executed this Agreement.", "public_sentence_id": 73}, {"id": 74, "field": "source_text", "start": 14412, "end": 14437, "text": "14. Signature Authority.", "public_sentence_id": 74}, {"id": 75, "field": "source_text", "start": 14437, "end": 14630, "text": "Each person signing below warrants that he or she has been duly authorized by the Participating Entity for whom he or she signs to execute this Agreement on behalf of that Participating Entity.", "public_sentence_id": 75}, {"id": 76, "field": "source_text", "start": 14631, "end": 14649, "text": "15. Counterparts.", "public_sentence_id": 76}, {"id": 77, "field": "source_text", "start": 14649, "end": 14757, "text": "This Agreement may be executed in counterparts, all of which shall be considered one and the same Agreement.", "public_sentence_id": 77}, {"id": 78, "field": "source_text", "start": 14758, "end": 14865, "text": "IN WITNESS WHEREOF, the Participating Entities have executed this Agreement as of the date set forth above.", "public_sentence_id": 78}, {"id": 79, "field": "source_text", "start": 14866, "end": 14873, "text": "Dated:", "public_sentence_id": 79}, {"id": 80, "field": "source_text", "start": 14873, "end": 14921, "text": "__________________________ Participating Entity:", "public_sentence_id": 80}, {"id": 82, "field": "source_text", "start": 14922, "end": 14926, "text": "By:", "public_sentence_id": 82}, {"id": 83, "field": "source_text", "start": 14926, "end": 14959, "text": "___________________________ Name:", "public_sentence_id": 83}, {"id": 85, "field": "source_text", "start": 14960, "end": 14966, "text": "Title:", "public_sentence_id": 85}], "tasks": {"nda-5": {"question": "Receiving Party may share some Confidential Information with some of Receiving Party's employees.", "native_annotation": {"answer": "Entailment", "evidence": [23]}}, "nda-7": {"question": "Receiving Party may share some Confidential Information with some third-parties (including consultants, agents and professional advisors).", "native_annotation": {"answer": "Contradiction", "evidence": [16, 17, 19]}}, "nda-16": {"question": "Receiving Party shall destroy or return some Confidential Information upon the termination of Agreement.", "native_annotation": {"answer": "Entailment", "evidence": [48]}}, "nda-20": {"question": "Receiving Party may retain some Confidential Information even after the return or destruction of Confidential Information.", "native_annotation": {"answer": "Entailment", "evidence": [51]}}}}, {"source": "ContractNLI:4d4e550ac17660215ea791c0b3a37cbef136c2e7642e6cbeb3cc9a3df43eeb40", "current_source_units": [{"id": 0, "field": "source_text", "start": 0, "end": 324, "text": "NON-DISCLOSURE AGREEMENT BY CLICKING "I ACCEPT" AT THE END OF THIS AGREEMENT, YOU ACKNOWLEDGE THAT YOU HAVE READ THIS AGREEMENT, THAT YOU UNDERSTAND IT AND ITS TERMS AND CONDITIONS, YOU HAVE THE ACTUAL AUTHORITY TO BIND YOUR COMPANY AND THAT YOU AND YOUR COMPANY AGREE TO BE BOUND LEGALLY BY IT AND ITS TERMS AND CONDITIONS.", "public_sentence_id": 0}, {"id": 2, "field": "source_text", "start": 325, "end": 676, "text": "THIS Non-Disclosure Agreement (the “Agreement”) is entered into on the date as of the registration (“Effective Date”) by and between Samsung Electronics Co., Ltd., a company existing under the laws of the Republic of Korea, with its place of business at 416 Maetan-3-Dong, Yeongtong-Gu, Suwon City, Gyeonggi-Do, Korea (“Samsung”), on the one part; and", "public_sentence_id": 2}, {"id": 5, "field": "source_text", "start": 677, "end": 897, "text": "[ COMPANY ], a company existing under the laws of the state/province of the above registration for the company during registration with its registered office above in the registration form (“Company”), on the other part.", "public_sentence_id": 5}, {"id": 6, "field": "source_text", "start": 898, "end": 1025, "text": "WHEREAS, the parties desire to evaluate the feasibility of the parties’ cooperation regarding KNOX Partnership (the “Purpose”).", "public_sentence_id": 6}, {"id": 7, "field": "source_text", "start": 1026, "end": 1272, "text": "WHEREAS, each party is willing to disclose to the other certain aspects of its Confidential Information (as defined hereinafter) relevant to and solely for the Purpose, subject to and in accordance with the terms and conditions of this Agreement.", "public_sentence_id": 7}, {"id": 8, "field": "source_text", "start": 1273, "end": 1447, "text": "NOW THEREFORE, in consideration of these premises and for other good and valuable consideration, receipt of which is hereby acknowledged, the parties hereto agree as follows:", "public_sentence_id": 8}, {"id": 9, "field": "source_text", "start": 1448, "end": 1477, "text": "1. Confidential Information.", "public_sentence_id": 9}, {"id": 10, "field": "source_text", "start": 1477, "end": 2047, "text": "“Confidential Information” includes all business, financial, contractual, marketing and/or technical information, in whatever form embodied, which has been or may be disclosed, or to which access is provided, by a party (“Discloser”) to the other party to this Agreement (“Recipient”), which (a) if in writing, is marked “confidential”, “proprietary” or other similar marking at the time of disclosure, or (b) if provided orally or visually, is identified as confidential at the time of disclosure and confirmed in writing to Recipient within 15 days of such disclosure.", "public_sentence_id": 10}, {"id": 13, "field": "source_text", "start": 2048, "end": 2691, "text": "Recipient may disclose Discloser’s Confidential Information to Recipient’s affiliates on the condition that Recipient shall restrict access to Discloser’s Confidential Information to those of Recipient’s affiliates’ officers, directors and employees who have a legitimate need-to-know to carry out the Purpose and who are obligated to protect such Confidential Information pursuant to terms and conditions no less protective of Discloser than those contained in this Agreement and Recipient shall be liable for any failure of its affiliates to abide by the provisions of this Agreement as if such failure was the act or omission of such party.", "public_sentence_id": 13}, {"id": 14, "field": "source_text", "start": 2692, "end": 3097, "text": "For the purposes of this Agreement, “affiliate” means an entity that, as of Effective Date, directly or indirectly, controls or is under common control with a party to this Agreement, but only for so long as such control exists, and where “control” shall mean ownership of more than 50% of the stock or other equity interests entitled to vote for the election of directors or an equivalent governing body.", "public_sentence_id": 14}, {"id": 15, "field": "source_text", "start": 3098, "end": 3139, "text": "2. Nondisclosure and Nonuse Obligations.", "public_sentence_id": 15}, {"id": 16, "field": "source_text", "start": 3139, "end": 3512, "text": "Each of the parties, as Recipient, hereby promises and agrees to receive and hold Confidential Information in confidence, and to protect and safeguard Confidential Information against unauthorized use or disclosure using at least the same degree of care as Recipient accords to its own confidential information of like importance, but in no case less than reasonable care.", "public_sentence_id": 16}, {"id": 17, "field": "source_text", "start": 3512, "end": 3616, "text": "Without limiting the generality of the foregoing, each party, as Recipient, further promises and agrees:", "public_sentence_id": 17}, {"id": 18, "field": "source_text", "start": 3617, "end": 3789, "text": "(a) not to, directly or indirectly, in any way, disclose, make accessible, reveal, report, publish, disseminate or transfer any Confidential Information to any third party;", "public_sentence_id": 18}, {"id": 19, "field": "source_text", "start": 3790, "end": 3935, "text": "(b) not to use any Confidential Information in any manner whatsoever, except in furtherance of the Purpose in accordance with this Agreement; and", "public_sentence_id": 19}, {"id": 20, "field": "source_text", "start": 3936, "end": 4268, "text": {"__lsg_shared_value__": "v1"}, "public_sentence_id": 20}, {"id": 21, "field": "source_text", "start": 4269, "end": 4377, "text": "(d) not to reproduce or copy Confidential Information except to the extent necessary to further the Purpose.", "public_sentence_id": 21}, {"id": 22, "field": "source_text", "start": 4378, "end": 4592, "text": "Furthermore, the existence of any business negotiations, discussions or agreements in progress between the parties shall be kept confidential and shall not be disclosed without written approval of all the parties.", "public_sentence_id": 22}, {"id": 23, "field": "source_text", "start": 4592, "end": 4787, "text": "For the purposes of this Agreement, Company shall not disclose Confidential Information to any other division, department, group, or unit other than Samsung KNOX Business and Technology Division.", "public_sentence_id": 23}, {"id": 24, "field": "source_text", "start": 4788, "end": 4820, "text": "3. Exclusions from Obligations.", "public_sentence_id": 24}, {"id": 25, "field": "source_text", "start": 4820, "end": 4965, "text": "Confidential Information does not include, and the obligations under Section 2 shall not apply to, information that such Recipient can evidence:", "public_sentence_id": 25}, {"id": 26, "field": "source_text", "start": 4965, "end": 5050, "text": "(a) is, or later becomes, publicly available through no act or default of Recipient;", "public_sentence_id": 26}, {"id": 27, "field": "source_text", "start": 5050, "end": 5133, "text": "(b) is rightfully in its possession prior to disclosure to Recipient by Discloser;", "public_sentence_id": 27}, {"id": 28, "field": "source_text", "start": 5133, "end": 5239, "text": "(c) is received in good faith by Recipient from a third party, free of any obligation of confidentiality;", "public_sentence_id": 28}, {"id": 29, "field": "source_text", "start": 5239, "end": 5338, "text": "(d) was communicated by such Discloser to an unaffiliated third party on an unrestricted basis; or", "public_sentence_id": 29}, {"id": 30, "field": "source_text", "start": 5338, "end": 5421, "text": "(e) is independently developed without use of Discloser’s Confidential Information.", "public_sentence_id": 30}, {"id": 31, "field": "source_text", "start": 5422, "end": 5898, "text": "A disclosure by Recipient of Confidential Information of another party in response to a valid order by a court or governmental body or as otherwise required by law shall not be considered to be a breach of this Agreement or a waiver of confidentiality for other purposes; provided, however, such Recipient shall provide prompt prior written notice thereof to Discloser and permit such Discloser to seek measures to maintain the confidentiality of its Confidential Information.", "public_sentence_id": 31}, {"id": 32, "field": "source_text", "start": 5899, "end": 5952, "text": "4. Ownership and Return of Confidential Information.", "public_sentence_id": 32}, {"id": 33, "field": "source_text", "start": 5952, "end": 6151, "text": "Confidential Information disclosed by Discloser shall remain the property of such Discloser, and no license or other rights to such Discloser’s Confidential Information is granted or implied hereby.", "public_sentence_id": 33}, {"id": 34, "field": "source_text", "start": 6151, "end": 6341, "text": "Recipient shall reproduce the symbols, legends or other proprietary notices affixed to Confidential Information, and shall not, nor permit any third party to, remove, add or modify the same.", "public_sentence_id": 34}, {"id": 35, "field": "source_text", "start": 6342, "end": 6794, "text": {"__lsg_shared_value__": "v3"}, "public_sentence_id": 35}, {"id": 36, "field": "source_text", "start": 6795, "end": 6822, "text": "5. No Reverse Engineering.", "public_sentence_id": 36}, {"id": 37, "field": "source_text", "start": 6822, "end": 7127, "text": "No party, as Recipient, will decompile, disassemble, reverse engineer or attempt to reconstruct, identify or discover any source code, underlying ideas, techniques or algorithms in Confidential Information by any means whatever, except as may be specifically authorized in advance by Discloser in writing.", "public_sentence_id": 37}, {"id": 38, "field": "source_text", "start": 7128, "end": 7144, "text": "6. No Warranty.", "public_sentence_id": 38}, {"id": 39, "field": "source_text", "start": 7144, "end": 7302, "text": "Confidential Information is provided “AS IS” and “AS AVAILABLE” without any warranty, express, implied or otherwise, regarding such Confidential Information.", "public_sentence_id": 39}, {"id": 40, "field": "source_text", "start": 7302, "end": 7500, "text": "Nothing herein shall be construed as a commitment by any party to disclose any Confidential Information, to commence or continue negotiations or to enter into any contract or business relationship.", "public_sentence_id": 40}, {"id": 41, "field": "source_text", "start": 7500, "end": 7755, "text": "Neither this Agreement, nor the disclosure or receipt of Confidential Information, shall constitute or imply any promise or intention by any of the parties or their affiliates to develop, make, purchase or sell any present or future products or services.", "public_sentence_id": 41}, {"id": 42, "field": "source_text", "start": 7755, "end": 7892, "text": "Any commitment to do or promise any of the foregoing must be in a separate writing signed by an authorized representative of each party.", "public_sentence_id": 42}, {"id": 43, "field": "source_text", "start": 7892, "end": 8028, "text": "If any such agreement contains warranty provisions, those provisions shall prevail over the corresponding provisions in this Agreement.", "public_sentence_id": 43}, {"id": 44, "field": "source_text", "start": 8028, "end": 8153, "text": "Each party shall bear its own fees, costs and expenses incurred in carrying out, or otherwise in relation to, this Agreement.", "public_sentence_id": 44}, {"id": 45, "field": "source_text", "start": 8154, "end": 8182, "text": "7. Independent Development.", "public_sentence_id": 45}, {"id": 46, "field": "source_text", "start": 8182, "end": 8569, "text": "This Agreement shall not preclude or limit the independent development by or on behalf of any party of any products or systems involving technology or information of a similar nature to that disclosed hereunder or which compete with products or systems contemplated by such information, provided that it is done without use of or reliance upon the other party’s Confidential Information.", "public_sentence_id": 46}, {"id": 47, "field": "source_text", "start": 8570, "end": 8595, "text": "8. Term and Termination.", "public_sentence_id": 47}, {"id": 48, "field": "source_text", "start": 8595, "end": 8681, "text": "This Agreement shall be effective from the Effective Date until 24 months thereafter.", "public_sentence_id": 48}, {"id": 49, "field": "source_text", "start": 8681, "end": 8792, "text": "Either party may terminate this Agreement for any or no reason upon 10 days written notice to the other party.", "public_sentence_id": 49}, {"id": 50, "field": "source_text", "start": 8792, "end": 8996, "text": "However, any termination of this Agreement shall not relieve Recipient of its confidentiality and use obligations with respect to Confidential Information disclosed prior to the date of such termination.", "public_sentence_id": 50}, {"id": 51, "field": "source_text", "start": 8996, "end": 9283, "text": "Except for the right to use Confidential Information for the Purpose, which right terminates when this Agreement terminates, Recipient’s duty to protect Discloser’s Confidential Information expires 5 years from the date on which that Confidential Information was disclosed to Recipient.", "public_sentence_id": 51}, {"id": 52, "field": "source_text", "start": 9283, "end": 9382, "text": "Sections 4, 5, 7, 8, 10, 11, 12, 13, 14, 15 and 16 shall survive any termination of this Agreement.", "public_sentence_id": 52}, {"id": 53, "field": "source_text", "start": 9383, "end": 9396, "text": "9. Contacts.", "public_sentence_id": 53}, {"id": 54, "field": "source_text", "start": 9396, "end": 9664, "text": "All notices, documentation and communications shall be in English and sent by personal delivery, pre-paid registered mail, overnight courier or facsimile transmission, to the relevant address set out below and shall be deemed to have been given on the date of receipt.", "public_sentence_id": 54}, {"id": 55, "field": "source_text", "start": 9666, "end": 9724, "text": "As record of this registration in the registration system.", "public_sentence_id": 56}, {"id": 56, "field": "source_text", "start": 9725, "end": 9737, "text": "10. Export.", "public_sentence_id": 57}, {"id": 57, "field": "source_text", "start": 9737, "end": 9976, "text": "Each party shall comply with all applicable US and other export laws, regulations and rules and, in particular, will not export or re-export Confidential Information without obtaining all required government licenses, approvals or waivers.", "public_sentence_id": 58}, {"id": 58, "field": "source_text", "start": 9977, "end": 9991, "text": "11. Remedies.", "public_sentence_id": 59}, {"id": 59, "field": "source_text", "start": 9991, "end": 10226, "text": "Each party acknowledges that any disclosure, use or misappropriation of Confidential Information of another party in violation of this Agreement would cause such party irreparable harm for which there may be no adequate remedy at law.", "public_sentence_id": 60}, {"id": 60, "field": "source_text", "start": 10226, "end": 10466, "text": "Accordingly, each party agrees that such other party shall have the right to apply to any court of competent jurisdiction for injunctive relief and specific performance, without prejudice to any remedies available to it at law or in equity.", "public_sentence_id": 61}, {"id": 61, "field": "source_text", "start": 10467, "end": 10483, "text": "12. Assignment.", "public_sentence_id": 62}, {"id": 62, "field": "source_text", "start": 10483, "end": 10771, "text": "No party shall be entitled to assign, transfer or convey this Agreement or any of its rights or obligations hereunder, in whole or in part, by operation of law or otherwise, without the prior written consent of the other party, and any attempt to do so without such consent shall be void.", "public_sentence_id": 63}, {"id": 63, "field": "source_text", "start": 10772, "end": 10787, "text": "13. No Waiver.", "public_sentence_id": 64}, {"id": 64, "field": "source_text", "start": 10787, "end": 10939, "text": "No claim, right or remedy of a party under this Agreement shall be deemed to be waived in whole or in part unless such waiver is in writing and signed.", "public_sentence_id": 65}, {"id": 65, "field": "source_text", "start": 10939, "end": 11261, "text": "No relaxation, forbearance, delay or indulgence by a party in enforcing any of the provisions of this Agreement shall prejudice, affect or restrict the rights of that party under this Agreement, nor shall any waiver by a party of a violation of this Agreement operate as a waiver of any subsequent or continuing violation.", "public_sentence_id": 66}, {"id": 66, "field": "source_text", "start": 11262, "end": 11280, "text": "14. Severability.", "public_sentence_id": 67}, {"id": 67, "field": "source_text", "start": 11280, "end": 11631, "text": "If any provision of this Agreement is held to be illegal, invalid or unenforceable, (i) that provision shall be deemed amended to achieve as nearly as possible the same economic effect as the original provision, and (ii) the legality, validity and enforceability of the remaining provisions of this Agreement shall not be affected or impaired thereby.", "public_sentence_id": 68}, {"id": 70, "field": "source_text", "start": 11632, "end": 11658, "text": "15. Law and Jurisdiction.", "public_sentence_id": 71}, {"id": 71, "field": "source_text", "start": 11658, "end": 11866, "text": "This Agreement shall be governed by and construed in accordance with the laws of the Republic of Korea (excluding conflict of laws provisions which may direct the application of another jurisdiction’s laws).", "public_sentence_id": 72}, {"id": 72, "field": "source_text", "start": 11866, "end": 12379, "text": "All disputes, controversies or claims between the parties arising out of or in connection with this Agreement (including its existence, validity or termination) shall be finally resolved by arbitration to be held in Seoul, Korea and conducted in English under the Rules of Arbitration of the International Chamber of Commerce; provided, however, that each party may enforce its or its affiliates’ intellectual property rights in any court of competent jurisdiction, including but not limited to equitable relief.", "public_sentence_id": 73}, {"id": 73, "field": "source_text", "start": 12379, "end": 12441, "text": "The arbitral award shall be final and binding on the parties.", "public_sentence_id": 74}, {"id": 74, "field": "source_text", "start": 12441, "end": 12625, "text": "Except to the extent entry of judgment and any subsequent enforcement may require disclosure, all matters relating to the arbitration, including the award, shall be held in confidence.", "public_sentence_id": 75}, {"id": 75, "field": "source_text", "start": 12626, "end": 12648, "text": "16. Entire Agreement.", "public_sentence_id": 76}, {"id": 76, "field": "source_text", "start": 12648, "end": 12855, "text": "This Agreement constitutes the entire agreement of the parties with respect to the subject matter hereof and may not be amended or modified except in writing signed by each of the parties to this Agreement.", "public_sentence_id": 77}, {"id": 77, "field": "source_text", "start": 12855, "end": 12944, "text": "The English language text of this Agreement shall prevail over any translations thereof.", "public_sentence_id": 78}, {"id": 78, "field": "source_text", "start": 12944, "end": 13275, "text": "If a contract is entered into by the parties in respect of the Purpose, this Agreement shall be deemed incorporated into such contract in addition to any confidentiality obligations set forth in such contract, if any, and the term of this Agreement is deemed to be extended (but not shorted) to be the same as that of the contract.", "public_sentence_id": 79}, {"id": 79, "field": "source_text", "start": 13276, "end": 13302, "text": "17. Electronic Signature.", "public_sentence_id": 80}, {"id": 80, "field": "source_text", "start": 13302, "end": 13460, "text": "The parties may execute this Agreement in counterparts, each of which is deemed an original, but all of which together constitute one and the same agreement.", "public_sentence_id": 81}, {"id": 81, "field": "source_text", "start": 13460, "end": 13615, "text": "This Agreement may be delivered by electronic mail communications in pdf format, and pdf copies of executed signature pages shall be binding as originals.", "public_sentence_id": 82}, {"id": 82, "field": "source_text", "start": 13615, "end": 13885, "text": "Each party to this Agreement agrees to use electronic signatures; and be subject to the provisions of the U.S. E-SIGN Act (i.e., the Electronic Signatures in Global and National Commerce Act (ESIGN, Pub.L. 106-229, 14 Stat. 464, enacted June 30, 2000, 15 U.S.C. ch. 96).", "public_sentence_id": 83}, {"id": 83, "field": "source_text", "start": 13886, "end": 14081, "text": "Per registration above from the person legally responsible to sign on behalf of their company accepts the contract above and is bound by and warrants the acceptance of the terms of this contract.", "public_sentence_id": 84}], "tasks": {"nda-5": {"question": "Receiving Party may share some Confidential Information with some of Receiving Party's employees.", "native_annotation": {"answer": "Entailment", "evidence": [13, 17, 20]}}, "nda-7": {"question": "Receiving Party may share some Confidential Information with some third-parties (including consultants, agents and professional advisors).", "native_annotation": {"answer": "Contradiction", "evidence": [13, 17, 18]}}, "nda-16": {"question": "Receiving Party shall destroy or return some Confidential Information upon the termination of Agreement.", "native_annotation": {"answer": "Entailment", "evidence": [35]}}, "nda-20": {"question": "Receiving Party may retain some Confidential Information even after the return or destruction of Confidential Information.", "native_annotation": {"answer": "Entailment", "evidence": [35]}}}}], "existing_TRAIN_source_review": [{"source_prefix": "354623", "actual_source_spans": [29, 30], "method_new_core_native_correct": 2, "control_new_core_native_correct": 2, "finding": "Both actually execute a return norm triggered by Volunteer service termination and an explicit prohibition on keeping copies/notes/abstracts. These actions and their cited evidence support the two target labels. SourceEffect retains service_termination distinct from agreement_termination; the ten-business-day deadline is not represented in either task-level norm.", "target_action_trigger_and_no_retention_supported": true, "all_contract_obligations_verified": false}, {"source_prefix": "d9360f", "actual_source_spans": [49, 50, 51], "method_new_core_native_correct": 2, "control_new_core_native_correct": 2, "finding": "Actual49 supplies Each party shall;50 supplies return within one month after Purpose completion or a written request;51 preserves confidentiality notwithstanding completion/return. SourceEffect cites50 without49 for its real duty, and also emits a false additional disposal duty from51. Its nda-16 proof uses both roots, so correct native output is not a valid complete source proof. The actual unchanged parse_disposal helper reproduces the false51 root. IndependentOpen cites47-50 for its duty but still simplifies the party/trigger structure.", "method_invalid_used_root": 3, "method_full_used_norm_semantics_verified": false}, {"source_prefix": "442c36", "actual_source_spans": [48, 49, 50, 51, 52, 53], "method_new_core_native_correct": 2, "control_new_core_native_correct": 2, "finding": "Both acquire termination return and the express legally required record-copy permission. SourceEffect preserves48's written-instruction exception; IndependentOpen incorrectly encodes no_exceptions there. Neither fully connects49's delayed backup destruction,50's certified-destruction alternative and52-53's notice, retention-expiry and continued-confidentiality duties to the return norm. The existential retention target is supported, while complete legal-effect scope remains partial.", "target_retention_permission_supported": true, "full_used_norm_semantics_verified": false}, {"source_prefix": "4d4e55", "actual_source_spans": [35], "method_new_core_native_correct": 2, "control_new_core_native_correct": 2, "finding": "Both acquire Agreement termination OR written request, a return/destroy alternative and the archival-copy exception. They omit Discloser's exclusive choice and the whichever-is-earlier/ten-day constraints. These omissions do not change the two existential native targets but prevent claiming complete norm preservation.", "target_effects_supported": true, "full_used_norm_semantics_verified": false}]}}
